// ProfileToProto converts the stored row (with its belongs-to associations,
// when preloaded) to its proto message. Nil in, nil out.
func ProfileToProto(m *Profile) *profilev1.Profile {
	if m == nil {
		return nil
	}
	out := &profilev1.Profile{}
	out.Name = m.Name
	out.Uid = fromPtr(m.UID)
	out.Etag = fromPtr(m.Etag)
	out.DeleteTime = goToTs(m.DeleteTime)
	out.ExpireTime = goToTs(m.ExpireTime)
	out.CreateTime = goValToTs(m.CreateTime)
	out.UpdateTime = goValToTs(m.UpdateTime)
	out.ShareAllSynchInd = YesNoPtrToProto(m.ShareAllSynchInd)
	out.ShareAllMarketInd = YesNoPtrToProto(m.ShareAllMarketInd)
	out.ShareAllOptOutInd = YesNoPtrToProto(m.ShareAllOptOutInd)
	out.OptinStatus = OptInChoicePtrToProto(m.OptinStatus)
	out.OptinTime = goToTs(m.OptinTime)
	out.OptOutTime = goToTs(m.OptOutTime)
	out.ProfileType = ProfileTypePtrToProto(m.ProfileType)
	out.CreatorId = fromPtr(m.CreatorID)
	out.LastModifierId = fromPtr(m.LastModifierID)
	out.Rph = fromPtr(m.Rph)
	out.StatusCodes = enumsFromCSV[codes.ProfileStatusCode](m.StatusCodes, codes.ProfileStatusCode_value)
	out.PurgeDay = DateToProto(m.PurgeDay)
	out.Accesses = AccessesToProto(m.Accesses)
	out.Customer = CustomerToProto(m.Customer)
	out.PrefCollections = PreferencesToProto(m.PrefCollections)
	out.CompanyInfo = CompanyInfoToProto(m.CompanyInfo)
	out.Affiliations = AffiliationsToProto(m.Affiliations)
	out.Agreements = AgreementsToProto(m.Agreements)
	for i := range m.Comments {
		out.Comments = append(out.Comments, CommentToProto(&m.Comments[i]))
	}
	return out
}

// ProfileFromProto maps the proto message's data fields onto a fresh row.
